{
  "status": "NEED_INFO",
  "summary": "Dự án LabBooking là một hệ thống web cho phép sinh viên đăng ký lịch sử dụng phòng thí nghiệm và quản trị viên phê duyệt yêu cầu, nhằm thay đổi phương thức quản lý bằng bảng tính truyền thống để tránh trùng lịch.",
  "deadline": {
    "value": "10/11/2026 23:59",
    "quote": "Mốc giữa kỳ: nộp bản thiết kế cơ sở dữ liệu trước 23:59 ngày 10/11/2026."
  },
  "requirements": [
    {
      "content": "Đăng ký/Đăng nhập bằng email trường, mật khẩu phải được băm (hash).",
      "quote": "Người dùng đăng ký, đăng nhập bằng email trường; mật khẩu phải được băm (hash) trước khi lưu."
    },
    {
      "content": "Xem lịch trống theo tuần và đặt phòng (phòng, ngày, ca).",
      "quote": "Sinh viên xem lịch trống theo tuần và gửi yêu cầu đặt phòng (chọn phòng, ngày, ca)."
    },
    {
      "content": "Tự động chặn các yêu cầu đặt phòng trùng với ca đã duyệt.",
      "quote": "Hệ thống tự động chặn yêu cầu đặt phòng bị trùng với ca đã được duyệt."
    },
    {
      "content": "Quản trị viên duyệt/từ chối và thông báo kết quả cho sinh viên qua ứng dụng.",
      "quote": "Quản trị viên duyệt hoặc từ chối yêu cầu; sinh viên nhận thông báo kết quả trong ứng dụng."
    },
    {
      "content": "Quản trị viên xuất báo cáo tần suất sử dụng phòng định dạng CSV.",
      "quote": "Quản trị viên xuất báo cáo tần suất sử dụng từng phòng theo tháng (định dạng CSV)."
    }
  ],
  "constraints": [
    {
      "content": "Nhóm thực hiện gồm 3 sinh viên.",
      "quote": "Bài tập thực hiện theo nhóm 3 sinh viên."
    },
    {
      "content": "Backend: Node.js (Express) hoặc Python (Django); DB: MySQL hoặc PostgreSQL.",
      "quote": "Backend sử dụng Node.js (Express) hoặc Python (Django); cơ sở dữ liệu quan hệ (MySQL hoặc PostgreSQL)."
    },
    {
      "content": "Cấm sử dụng nền tảng low-code/no-code (Firebase, Bubble...).",
      "quote": "Không sử dụng nền tảng low-code/no-code (Firebase, Bubble...)."
    },
    {
      "content": "Giao diện phải tương thích với thiết bị di động (Responsive).",
      "quote": "Giao diện hiển thị tốt trên màn hình điện thoại (responsive)."
    },
    {
      "content": "Sử dụng Git, mỗi thành viên tối thiểu 10 commit.",
      "quote": "Mã nguồn quản lý bằng Git, mỗi thành viên có tối thiểu 10 commit."
    }
  ],
  "deliverables": [
    {
      "content": "Báo cáo PDF (phân tích, CSDL, kiến trúc, cài đặt) không quá 20 trang.",
