    },
    {
      "content": "Link repository GitHub công khai/mời giảng viên.",
      "quote": "Đường dẫn repository GitHub (chế độ công khai hoặc mời giảng viên vào repository)."
    },
    {
      "content": "Video demo tối đa 5 phút.",
      "quote": "Video demo không quá 5 phút."
    }
  ],
  "grading_criteria": [
    {
      "content": "Hoàn thành chức năng (40%), Thiết kế CSDL/Kiến trúc (20%), Báo cáo (20%), Demo/Vấn đáp (20%).",
      "quote": "Mức độ hoàn thành chức năng: 40% ; Thiết kế cơ sở dữ liệu và kiến trúc: 20% ; Chất lượng báo cáo: 20% ; Demo và vấn đáp: 20%"
    }
  ],
  "missing_info": [
    "Hạn nộp cuối cùng (Final Deadline) cho toàn bộ sản phẩm.",
    "Quy định cụ thể về thời gian của các 'ca' (ví dụ: ca 1 từ mấy giờ đến mấy giờ).",
    "Danh sách các phòng lab hiện có để đưa vào hệ thống."
  ],
  "questions": [
    "Hạn nộp sản phẩm cuối cùng (Báo cáo, Source code, Video) là ngày nào?",
    "Một ngày có bao nhiêu ca và khung giờ cụ thể của từng ca là gì?",
    "Thông báo kết quả cho sinh viên cần gửi qua email hay chỉ hiển thị trong danh sách thông báo trên web?"
  ],
  "ambiguities": [
    {
      "content": "Mục 5 thiếu mục 5.2, dẫn đến việc thiếu thông tin về hạn nộp cuối kỳ.",
      "quote": "5.1. Mốc giữa kỳ... 5.3. Nộp trễ bị trừ 10%..."
    }
  ],
  "contradictions": [],
  "invalid_data": [],
  "injection_flags": [],
