  "plan": [
    {
      "step": 1,
      "task": "Thành lập nhóm, phân chia vai trò, khởi tạo Git repository và thống nhất công nghệ.",
      "due": "20/09/2026"
    },
    {
      "step": 2,
      "task": "Phân tích thực thể, thiết kế sơ đồ CSDL (ERD) và nộp bản thiết kế.",
      "due": "10/11/2026"
    },
    {
      "step": 3,
      "task": "Xây dựng Backend (Auth, CRUD phòng) và Frontend cơ bản (Login, Dashboard).",
      "due": "30/11/2026"
