    {
      "step": 4,
      "task": "Phát triển logic đặt phòng, xử lý chặn trùng lịch và giao diện responsive.",
      "due": "15/12/2026"
    },
    {
      "step": 5,
      "task": "Hoàn thiện chức năng Admin (Duyệt lịch, Xuất CSV) và thông báo.",
      "due": "30/12/2026"
    },
    {
      "step": 6,
      "task": "Viết báo cáo PDF, quay video demo và kiểm tra lại số lượng commit của từng thành viên.",
      "due": "10/01/2027"
    }
  ]
